components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  width: 100%;
  height: 42px;
  padding: 0 18px;
  border: 1px solid transparent;
  border-radius: var(--ofs-r-md, 14px);
  background: var(--ofs-accent-grad, linear-gradient(180deg, #2b2b30 0%, #141416 100%));
  color: var(--ofs-accent-ink, #ffffff);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 13.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  white-space: nowrap;
  box-shadow: var(--ofs-shadow-accent, 0 8px 18px -10px rgb(16 16 20 / 48%));
  cursor: pointer;
  transition: transform 160ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 160ms ease, opacity 160ms ease;
}
.ds-btn-primary:hover:not(:disabled) {
  transform: translateY(-1px);
  box-shadow: 0 14px 28px -12px rgb(16 16 20 / 50%);
}
.ds-btn-primary:active:not(:disabled) {
  transform: translateY(0) scale(0.99);
}
.ds-btn-primary:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-btn-primary:disabled {
  opacity: 0.36;
  filter: saturate(0.6);
  box-shadow: none;
  cursor: default;
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 11px;
  border: 1px solid var(--ofs-sunken-border, rgb(18 18 22 / 8%));
  border-radius: var(--ofs-r-pill, 999px);
  background: color-mix(in oklab, var(--ofs-card, #ffffff) 78%, transparent);
  color: var(--ofs-ink-2, #52525a);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 11.5px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}
.ds-btn-secondary:hover {
  border-color: var(--ofs-accent-soft-border, #dedee3);
  background: var(--ofs-accent-soft, #f0f0f2);
  color: var(--ofs-accent, #141416);
}
.ds-btn-secondary:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-btn-secondary:disabled {
  color: var(--ofs-ink-4, #a8a8b0);
  cursor: default;
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-glass-btn {
  display: grid;
  place-items: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid var(--ofs-window-border, rgb(18 18 22 / 8%));
  border-radius: 11px;
  background: color-mix(in oklab, var(--ofs-card-solid, #ffffff) 68%, transparent);
  color: var(--ofs-ink-2, #52525a);
  box-shadow: var(--ofs-shadow-card, 0 1px 2px rgb(16 16 20 / 5%), 0 10px 24px -16px rgb(16 16 20 / 22%));
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  cursor: pointer;
  transition: color 150ms ease, border-color 150ms ease, background-color 150ms ease, transform 150ms cubic-bezier(0.22, 1, 0.36, 1);
}
.ds-glass-btn:hover {
  border-color: var(--ofs-accent-soft-border, #dedee3);
  color: var(--ofs-accent, #141416);
}
.ds-glass-btn:active {
  transform: scale(0.95);
}
.ds-glass-btn:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-glass-btn.ds-is-on {
  color: var(--ofs-accent, #141416);
  background: var(--ofs-accent-soft, #f0f0f2);
  border-color: var(--ofs-accent-soft-border, #dedee3);
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-segmented {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border: 1px solid var(--ofs-sunken-border, rgb(18 18 22 / 8%));
  border-radius: var(--ofs-r-pill, 999px);
  background: var(--ofs-sunken, #f4f4f6);
}
.ds-segmented-btn {
  appearance: none;
  height: 26px;
  padding: 0 12px;
  border: 0;
  border-radius: var(--ofs-r-pill, 999px);
  background: transparent;
  color: var(--ofs-ink-2, #52525a);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 12px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 160ms ease, color 160ms ease, box-shadow 160ms ease;
}
.ds-segmented-btn:hover {
  color: var(--ofs-accent, #141416);
}
.ds-segmented-btn.ds-is-on {
  background: var(--ofs-card-solid, #ffffff);
  color: var(--ofs-ink, #141416);
  font-weight: 600;
  box-shadow: 0 1px 2px rgb(16 16 20 / 8%);
}
.ds-segmented-btn:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}

.ds-composer {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 10px 10px 7px;
  border: 1px solid var(--ofs-sunken-border, rgb(18 18 22 / 8%));
  border-radius: var(--ofs-r-md, 14px);
  background: linear-gradient(180deg, var(--ofs-card-solid, #ffffff) 0%, var(--ofs-sunken, #f4f4f6) 100%);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  transition: border-color 160ms ease, box-shadow 160ms ease;
}
.ds-composer:focus-within {
  border-color: var(--ofs-accent-soft-border, #dedee3);
  box-shadow: 0 0 0 3px rgb(20 20 22 / 10%);
}
.ds-composer-input {
  width: 100%;
  min-height: 66px;
  padding: 0;
  border: 0;
  outline: none;
  resize: none;
  background: transparent;
  color: var(--ofs-ink, #141416);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 13px;
  line-height: 1.62;
}
.ds-composer-input::placeholder {
  color: var(--ofs-ink-3, #6b6b73);
}
.ds-composer-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.ds-composer-counter {
  font-size: 11px;
  color: var(--ofs-ink-3, #6b6b73);
  font-variant-numeric: tabular-nums;
}
.ds-composer-action {
  padding: 3px 7px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ofs-accent, #141416);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 11.5px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 150ms ease;
}
.ds-composer-action:hover {
  background: var(--ofs-accent-soft, #f0f0f2);
}

.ds-compute-row {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
}
.ds-compute {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 11px;
  border: 1px solid var(--ofs-card-border, rgb(18 18 22 / 9%));
  border-radius: var(--ofs-r-pill, 999px);
  background: var(--ofs-card, #ffffff);
  color: var(--ofs-ink-2, #52525a);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 12px;
  font-weight: 550;
  white-space: nowrap;
  box-shadow: var(--ofs-shadow-card, 0 1px 2px rgb(16 16 20 / 5%), 0 10px 24px -16px rgb(16 16 20 / 22%));
  cursor: pointer;
  transition: border-color 160ms ease, color 160ms ease, background-color 160ms ease;
}
.ds-compute:hover {
  border-color: var(--ofs-accent-soft-border, #dedee3);
  color: var(--ofs-ink, #141416);
}
.ds-compute:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-compute em {
  font-style: normal;
  font-size: 11px;
  color: var(--ofs-ink-3, #6b6b73);
  font-variant-numeric: tabular-nums;
}
.ds-compute-dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--ofs-idle, #a0a0a8);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ofs-idle, #a0a0a8) 22%, transparent);
}
.ds-compute-dot.ds-is-ok {
  background: var(--ofs-ok, #2f8a5c);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ofs-ok, #2f8a5c) 20%, transparent);
  animation: ds-pulse 2.4s ease-out infinite;
}
.ds-compute-dot.ds-is-warn {
  background: var(--ofs-warn, #a96a18);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ofs-warn, #a96a18) 22%, transparent);
}
.ds-compute-dot.ds-is-error {
  background: var(--ofs-error, #c04444);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ofs-error, #c04444) 20%, transparent);
}
@keyframes ds-pulse {
  0% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--ofs-ok, #2f8a5c) 34%, transparent); }
  70% { box-shadow: 0 0 0 6px color-mix(in oklab, var(--ofs-ok, #2f8a5c) 0%, transparent); }
  100% { box-shadow: 0 0 0 0 color-mix(in oklab, var(--ofs-ok, #2f8a5c) 0%, transparent); }
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.ds-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 12px;
  border: 1px solid var(--ofs-sunken-border, rgb(18 18 22 / 8%));
  border-radius: var(--ofs-r-pill, 999px);
  background: var(--ofs-card, #ffffff);
  color: var(--ofs-ink-2, #52525a);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  font-size: 12px;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease, color 150ms ease;
}
.ds-chip:hover {
  border-color: var(--ofs-accent-soft-border, #dedee3);
  color: var(--ofs-ink, #141416);
}
.ds-chip.ds-is-on {
  background: var(--ofs-accent-soft, #f0f0f2);
  border-color: var(--ofs-accent-soft-border, #dedee3);
  color: var(--ofs-accent, #141416);
}
.ds-chip.ds-is-danger {
  border-color: transparent;
  background: var(--ofs-error-soft, #f9ecec);
  color: var(--ofs-error, #c04444);
}
.ds-chip.ds-is-danger:hover {
  border-color: var(--ofs-error, #c04444);
  color: var(--ofs-error, #c04444);
}
.ds-chip:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-gallery-card {
  display: block;
  width: 100%;
  margin: 0;
  padding: 6px;
  border: 1px solid var(--ofs-card-border, rgb(18 18 22 / 9%));
  border-radius: var(--ofs-r-lg, 18px);
  background: var(--ofs-card, #ffffff);
  color: var(--ofs-ink, #141416);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  text-align: left;
  box-shadow: var(--ofs-shadow-card, 0 1px 2px rgb(16 16 20 / 5%), 0 10px 24px -16px rgb(16 16 20 / 22%));
  cursor: pointer;
  transition: transform 180ms cubic-bezier(0.22, 1, 0.36, 1), box-shadow 180ms ease, border-color 180ms ease;
}
.ds-gallery-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--ofs-shadow-lift, 0 2px 6px rgb(16 16 20 / 6%), 0 18px 40px -20px rgb(16 16 20 / 26%));
}
.ds-gallery-card:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
.ds-gallery-media {
  position: relative;
  display: block;
  overflow: hidden;
  border-radius: calc(var(--ofs-r-lg, 18px) - 7px);
  background: var(--ofs-sunken, #f4f4f6);
}
.ds-gallery-placeholder {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 140px;
  background:
    radial-gradient(90% 120% at 22% 0%, #d8d8dd 0%, transparent 58%),
    linear-gradient(155deg, #a9a9b1 0%, #6f6f78 45%, #303035 100%);
}
.ds-gallery-star {
  position: absolute;
  top: 8px;
  right: 8px;
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: color-mix(in oklab, var(--ofs-card-solid, #ffffff) 84%, transparent);
  color: var(--ofs-ink, #141416);
  box-shadow: 0 1px 4px rgb(24 24 27 / 22%);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
}
.ds-gallery-body {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 10px 8px 8px;
}
.ds-gallery-caption {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  color: var(--ofs-ink, #141416);
  font-size: 12.5px;
  font-weight: 500;
  line-height: 1.5;
  word-break: break-word;
}
.ds-gallery-tags {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--ofs-ink-3, #6b6b73);
  font-size: 11px;
  line-height: 1.3;
}
.ds-gallery-tags em {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  font-style: normal;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.ds-gallery-tags span {
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
}
.ds-icon {
  flex: 0 0 auto;
}

.ds-panel {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 360px;
  overflow: hidden;
  border: 1px solid var(--ofs-card-border, rgb(18 18 22 / 9%));
  border-radius: var(--ofs-r-lg, 18px);
  background: var(--ofs-card, #ffffff);
  color: var(--ofs-ink, #141416);
  font-family: -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  box-shadow: var(--ofs-shadow-card, 0 1px 2px rgb(16 16 20 / 5%), 0 10px 24px -16px rgb(16 16 20 / 22%));
}
.ds-panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 15px 15px 11px;
}
.ds-panel-title {
  margin: 0;
  font-size: 16px;
  font-weight: 650;
  letter-spacing: 0.01em;
  white-space: nowrap;
}
.ds-panel-meta {
  font-size: 11px;
  color: var(--ofs-ink-3, #6b6b73);
  white-space: nowrap;
}
.ds-panel-body {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 0 15px 14px;
  border-top: 1px solid var(--ofs-hairline, rgb(18 18 22 / 7%));
  padding-top: 10px;
}
.ds-panel-field {
  margin: 0;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--ofs-ink-2, #52525a);
}
.ds-panel-well {
  padding: 10px 11px;
  border: 1px solid var(--ofs-sunken-border, rgb(18 18 22 / 8%));
  border-radius: 10px;
  background: var(--ofs-sunken, #f4f4f6);
  color: var(--ofs-ink-3, #6b6b73);
  font-size: 12px;
  line-height: 1.55;
}
.ds-panel-foot {
  padding: 12px 15px 14px;
  border-top: 1px solid var(--ofs-hairline, rgb(18 18 22 / 7%));
  box-shadow: 0 -16px 20px -18px rgb(16 16 20 / 20%);
  color: var(--ofs-ink-3, #6b6b73);
  font-size: 10.5px;
  text-align: center;
}

.ds-thumb-row {
  display: flex;
  gap: 6px;
}
.ds-thumb {
  display: block;
  width: 62px;
  height: 62px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 12px;
  background: var(--ofs-sunken, #f4f4f6);
  overflow: hidden;
  cursor: pointer;
  transition: transform 170ms cubic-bezier(0.22, 1, 0.36, 1), border-color 170ms ease, box-shadow 170ms ease;
}
.ds-thumb-art {
  display: block;
  width: 100%;
  height: 100%;
  background:
    radial-gradient(80% 100% at 30% 0%, #e9e9ec 0%, transparent 55%),
    linear-gradient(150deg, #c9c9cf 0%, #8a8a93 48%, #3a3a40 100%);
}
.ds-thumb:hover {
  transform: translateY(-2px);
}
.ds-thumb.ds-is-on {
  border-color: var(--ofs-accent, #141416);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--ofs-accent, #141416) 20%, transparent);
}
.ds-thumb:focus-visible {
  outline: none;
  box-shadow: var(--ofs-focus-ring, 0 0 0 2px #ffffff, 0 0 0 4px rgb(20 20 22 / 45%));
}
